<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>BIR Annual Compensation Report</title><style>body{font-family:Arial;font-size:11px}h1{text-align:center;font-size:16px}p{text-align:center;color:#555}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:6px}th{background:#f2f2f2}.right{text-align:right}</style></head><body><h1>MOTHER THERESA COLEGIO GROUP OF SCHOOLS</h1><p>BIR Annual Compensation Summary | Calendar Year <?php echo e($year); ?></p><table><thead><tr><th>Employee</th><th>Employee #</th><th>Gross Compensation</th><th>SSS</th><th>PhilHealth</th><th>Pag-IBIG</th><th>Withholding Tax</th><th>Net Pay</th></tr></thead><tbody><?php $__currentLoopData = $entries; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $employeeEntries): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?> <?php $employee = $employeeEntries->first()->employeeProfile; ?><tr><td><?php echo e($employee->full_name ?? 'N/A'); ?></td><td><?php echo e($employee->employee_number ?? 'N/A'); ?></td><td class="right">₱<?php echo e(number_format($employeeEntries->sum('basic_pay'), 2)); ?></td><td class="right">₱<?php echo e(number_format($employeeEntries->sum('sss_contribution'), 2)); ?></td><td class="right">₱<?php echo e(number_format($employeeEntries->sum('philhealth_contribution'), 2)); ?></td><td class="right">₱<?php echo e(number_format($employeeEntries->sum('pagibig_contribution'), 2)); ?></td><td class="right">₱<?php echo e(number_format($employeeEntries->sum('withholding_tax'), 2)); ?></td><td class="right">₱<?php echo e(number_format($employeeEntries->sum('net_pay'), 2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table><p>System-generated annual compensation summary. Verify values with Finance before filing official BIR forms.</p></body></html>
